VIEW_CODES = [
    "activity.view",
    "equipment.view",
    "farms.view",
    "inquiries.view",
    "users.view",
]


def grant_views_to_existing_members(apps, schema_editor):
    """
    Until now every member could read everything, so give every existing
    staff account the view codes: nobody loses access on deploy, and an admin
    can narrow them afterwards. Owners hold everything implicitly.
    """
    User = apps.get_model("users", "User")
    Organization = apps.get_model("users", "Organization")
    owners = Organization.objects.exclude(owner__isnull=True).values("owner_id")
    for user in User.objects.filter(organization__isnull=False).exclude(pk__in=owners):
        user.permissions = sorted({*(user.permissions or []), *VIEW_CODES})
        user.save(update_fields=["permissions"])


